from pathlib import Path
import json,base64
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'choir-studio/public/designs';OUT.mkdir(exist_ok=True)
score_dir=ROOT/'choir-studio/public/songs/chi-le-ge'
song=json.loads((score_dir/'song.json').read_text(encoding='utf8'))
preview=dict(song)
preview['systems']=song['systems'][:2]
preview['measures']=[m for m in song['measures'] if m['system']<2]
preview['pages']=song['pages'][:1]
svg=base64.b64encode((score_dir/song['pages'][0]['svg']).read_bytes()).decode()
layout=(ROOT/'choir-studio/public/reading-layout.js').read_text(encoding='utf8').replace('export function','function')
CSS='''
*{box-sizing:border-box}body{margin:0;font-family:Arial,"PingFang SC","Microsoft YaHei",sans-serif;color:var(--ink);background:var(--bg)}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}button,select{border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:var(--radius);min-height:34px;padding:5px 10px}button:hover{border-color:var(--accent)}button.on{background:var(--accent);border-color:var(--accent);color:white}a{color:inherit}.variant{height:35px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:11px;background:#fff;color:#555;border-bottom:1px solid #ddd}.variant nav{display:flex;gap:14px}.variant a{text-decoration:none}.variant a.active{font-weight:bold;color:#111}.workbench{height:calc(100dvh - 35px);min-height:450px;display:grid;overflow:hidden}.toolbar{display:flex;align-items:center;justify-content:space-between;padding:0 18px;gap:12px;background:var(--panel);border-bottom:1px solid var(--line)}.toolbar-left,.toolbar-right{display:flex;gap:9px;align-items:center}.toolbar strong{font-size:14px;font-weight:600}.toolbar .divider{width:1px;background:var(--line);height:20px;margin:0 5px}.toolbar .fine{font-size:11px;color:var(--muted)}.library{padding:24px 16px;background:var(--panel);border-right:1px solid var(--line);font-size:13px}.library h3{font-size:11px;text-transform:none;color:var(--muted);font-weight:400;margin:0 0 16px}.library button{display:block;width:100%;text-align:left;line-height:1.6;margin-bottom:8px;border-color:transparent;padding:10px}.library button.active{border-color:var(--line);border-left:3px solid var(--accent);background:var(--selected)}.library button span{display:block;font-size:10px;color:var(--muted)}.library .section{margin-top:32px;font-size:11px;color:var(--muted)}.library p{font-size:12px;line-height:2;color:var(--muted)}.score{display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--bg)}.score-meta{min-height:75px;display:flex;justify-content:space-between;align-items:center;padding:13px 23px;border-bottom:1px solid var(--line);gap:10px}.score-meta h1{font-size:24px;font-weight:500;margin:0 0 6px}.score-meta p{font-size:11px;color:var(--muted);margin:0}.view-tools{display:flex;align-items:center;gap:7px;font-size:11px}.view-tools button{min-width:34px}.paper-scroll{flex:1;min-height:0;overflow:auto;padding:20px 22px;background:var(--bg)}.paper{background:#fff;color:#111;padding:20px 20px 30px;min-height:100%;border:1px solid var(--paper-line)}.paper-heading{text-align:center;margin:0 0 24px;font-family:Georgia,"Songti SC",SimSun,serif;color:#222}.paper-heading h2{font-weight:400;font-size:27px;letter-spacing:7px;margin:0 0 8px}.paper-heading p{font-size:10px;color:#777;margin:0}.notation-row{margin:0 0 24px}.notation-row small{display:block;font-size:10px;color:#777;margin-bottom:7px}.row-scroll{overflow-x:auto;overflow-y:hidden}.notation-line{display:flex;position:relative;background:#fff}.notation-line svg{display:block;flex:none;height:100%}.notation-line .cursor{position:absolute;top:0;bottom:0;left:47%;width:2px;background:var(--accent);opacity:.65;pointer-events:none}.notation-line .shade{position:absolute;top:0;bottom:0;left:32%;width:26%;background:var(--accent);opacity:.06;pointer-events:none}.controls{background:var(--panel);border-left:1px solid var(--line);padding:20px 18px;overflow:auto;min-height:0}.controls h2{font-size:14px;font-weight:600;margin:0 0 15px}.control-title{display:flex;align-items:center;justify-content:space-between}.controls .close{display:none}.preset{display:flex;gap:5px;margin-bottom:14px}.preset button{flex:1;font-size:11px}.track{padding:13px 0;border-top:1px solid var(--line)}.track-title{display:flex;align-items:center;gap:8px;font-size:12px;min-height:28px}.track-title label{flex:1;display:flex;align-items:center;gap:8px}.track-title input{accent-color:var(--accent);width:15px;height:15px}.solo{font-size:10px;min-height:27px;padding:3px 7px}.track select{display:block;width:100%;font-size:10px;min-height:28px;margin:7px 0;color:var(--muted)}.volume{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--muted)}.volume input{width:100%;accent-color:var(--accent);height:4px}.branch-list{margin:8px 0 0 23px;border-left:1px solid var(--line);padding-left:10px;display:flex;gap:13px;flex-wrap:wrap}.branch-list label{font-size:10px;display:flex;align-items:center;gap:4px}.branch-list input{accent-color:var(--accent);width:13px;height:13px}.expression{font-size:11px;display:flex;justify-content:space-between;align-items:center;padding-top:18px;margin-top:12px;border-top:1px solid var(--line)}.expression input{accent-color:var(--accent)}.footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:10px 20px;border-top:1px solid var(--line);background:var(--panel)}.transport{display:flex;gap:7px;align-items:center;flex-shrink:0}.transport .play{min-width:44px;background:var(--accent);border-color:var(--accent);color:#fff}.timeline{display:flex;align-items:center;gap:12px;flex:1;max-width:560px;font-size:11px;font-variant-numeric:tabular-nums}.timeline input{width:100%;accent-color:var(--accent);height:4px}.speed{display:flex;gap:7px;align-items:center;font-size:11px}.speed select{font-size:12px}.mobile-control{display:none}.scrim{display:none}.meter{display:none}.status{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-top:14px}.muted{opacity:.4}
/* A: utility-first notation application */
.a{--ink:#22272c;--muted:#717981;--bg:#e9ecef;--panel:#f7f8f9;--line:#d1d6db;--selected:#e6edf5;--accent:#315f87;--paper-line:#d1d6db;--radius:2px}.a .workbench{grid-template-columns:178px minmax(0,1fr) 252px;grid-template-rows:48px minmax(0,1fr) 70px}.a .toolbar{grid-column:1/4}.a .library{grid-column:1;grid-row:2}.a .score{grid-column:2;grid-row:2}.a .controls{grid-column:3;grid-row:2}.a .footer{grid-column:1/4}.a .score-meta{background:#f7f8f9}.a .paper-heading{display:none}
/* B: quiet, print-oriented score reader */
.b{--ink:#302c28;--muted:#847c71;--bg:#e9e3d8;--panel:#f6f2e9;--line:#d9d0c2;--selected:#eee4d8;--accent:#8a3b31;--paper-line:#d6cec1;--radius:0}.b .workbench{grid-template-columns:minmax(0,1fr) 266px;grid-template-rows:64px minmax(0,1fr) 74px}.b .toolbar{grid-column:1/3;background:#faf7f0;padding:0 28px}.b .toolbar strong{font-family:Georgia,"Songti SC",SimSun,serif;letter-spacing:3px;font-size:19px}.b .library{display:none}.b .score{grid-column:1;grid-row:2}.b .score-meta{min-height:56px;border:0;padding:10px 28px}.b .score-meta h1{font-size:16px;margin:0;display:inline}.b .score-meta p{display:none}.b .paper-scroll{padding:0 28px 25px}.b .paper{padding:30px 25px}.b .controls{grid-column:2;grid-row:2;background:#f6f2e9;padding-top:23px}.b .footer{grid-column:1/3;background:#faf7f0}.b .preset button{background:transparent}.b .track-title label{font-family:"Songti SC",SimSun,serif;font-size:14px}.b .track{padding:15px 0}.b .toolbar button{background:transparent;border-color:transparent}.b .toolbar button:hover{border-color:var(--line)}
/* C: compact rehearsal mixing console */
.c{--ink:#e1e3e5;--muted:#a0a7ae;--bg:#373c42;--panel:#262a2e;--line:#484d53;--selected:#41464d;--accent:#a87527;--paper-line:#555b62;--radius:2px}.c .workbench{grid-template-columns:1fr;grid-template-rows:48px minmax(0,1fr) 191px 62px}.c .toolbar{grid-column:1;grid-row:1}.c .library{display:none}.c .score{grid-row:2}.c .score-meta{min-height:44px;padding:8px 20px;background:#30353a}.c .score-meta h1{font-size:16px;margin:0}.c .score-meta p{display:none}.c .paper-scroll{padding:15px 22px}.c .paper{padding-top:12px}.c .paper-heading{display:none}.c .controls{grid-row:3;display:flex;gap:0;border-top:1px solid var(--line);border-left:0;padding:0;overflow:auto}.c .controls>.control-title{flex:0 0 105px;padding:16px;display:block}.c .controls h2{font-size:12px;line-height:1.8}.c .controls .preset{display:block}.c .controls .preset button{font-size:10px;padding:4px;min-height:25px;margin:5px 0;width:70px}.c .tracks{display:flex;flex:1}.c .track{flex:1;min-width:132px;border-top:0;border-left:1px solid var(--line);padding:12px}.c .track select{background:#202428;font-size:10px}.c .track-title{font-size:11px}.c .track-title label{gap:5px}.c .track-title input{width:12px;height:12px}.c .branch-list{margin:6px 0 0;padding:0;border:0;gap:5px}.c .branch-list label{font-size:9px}.c .volume{margin-top:12px}.c .meter{display:block;height:5px;margin:13px 0 0;background:#191b1e;position:relative}.c .meter:before{content:"";position:absolute;inset:0 23% 0 0;background:repeating-linear-gradient(90deg,#7fa17b 0 7px,#262a2e 7px 9px)}.c .expression,.c .status{display:none}.c .footer{grid-row:4;padding:8px 20px}.c .timeline{max-width:700px}.c .on{color:#fff!important}.c .score .view-tools{font-size:11px}
@media(max-width:1050px){.a .workbench{grid-template-columns:minmax(0,1fr) 245px}.a .toolbar,.a .footer{grid-column:1/3}.a .library{display:none}.a .score{grid-column:1}.a .controls{grid-column:2}.b .workbench{grid-template-columns:minmax(0,1fr) 240px}.toolbar .fine{display:none}.toolbar{padding-left:15px;padding-right:15px}.paper-scroll{padding:14px}.paper{padding-left:12px;padding-right:12px}}
@media(max-width:700px){.variant{height:32px;padding:0 10px;font-size:10px}.variant .note{display:none}.variant nav{gap:12px}.workbench{height:calc(100dvh - 32px);min-height:450px}.a .workbench,.b .workbench{grid-template-columns:minmax(0,1fr);grid-template-rows:48px minmax(0,1fr) 110px}.a .toolbar,.b .toolbar,.a .footer,.b .footer{grid-column:1}.a .score,.b .score{grid-column:1;grid-row:2}.mobile-control{display:inline-block}.toolbar{padding:0 11px!important}.toolbar strong{font-size:13px!important;letter-spacing:0!important}.toolbar-right{gap:5px}.toolbar-right .optional{display:none}.toolbar button{font-size:11px;padding:5px 8px;min-height:34px}.score-meta{min-height:66px;padding:10px 12px}.score-meta h1{font-size:20px}.score-meta p{max-width:190px;font-size:10px;line-height:1.5}.view-tools{gap:4px}.view-tools .optional{display:none}.view-tools button{padding:5px;min-width:32px}.paper-scroll,.b .paper-scroll{padding:10px}.paper,.b .paper{padding:14px 8px}.paper-heading{margin-bottom:17px}.paper-heading h2{font-size:24px}.a .controls,.b .controls{display:none;position:fixed;inset:32px 0 110px auto;width:min(310px,90vw);z-index:10;border-left:1px solid var(--line);padding:18px;overflow:auto}.a .controls.open,.b .controls.open{display:block}.controls .close{display:block;min-width:32px;min-height:32px;padding:4px;font-size:20px}.scrim.open{display:block;position:fixed;inset:32px 0 110px;background:#0005;z-index:9}.footer{display:grid!important;grid-template-columns:1fr auto;gap:8px;padding:9px 14px!important}.transport{grid-column:1;grid-row:1}.timeline{grid-column:1/3;grid-row:2;max-width:none;font-size:10px;gap:8px}.speed{grid-column:2;grid-row:1;gap:5px;font-size:10px}.speed select{min-height:33px;font-size:11px}.transport button{min-height:38px;min-width:36px}.transport .optional{display:none}.b .toolbar strong{font-size:17px!important;letter-spacing:2px!important}.b .score-meta{min-height:48px}.c .workbench{grid-template-rows:46px minmax(0,1fr) 171px 103px}.c .toolbar-right .optional{display:none}.c .score-meta{padding:6px 10px;min-height:40px}.c .paper-scroll{padding:8px}.c .controls{height:171px}.c .controls>.control-title{display:none}.c .track{min-width:132px;padding:10px}.c .track-title{font-size:11px}.c .track select{min-height:27px}.c .meter{margin-top:10px}.c .footer{grid-row:4}.c .mobile-control{display:none}.c .paper{padding:10px 7px}}
@media(max-height:550px) and (min-width:701px){.workbench{min-height:0}.score-meta{min-height:40px}.c .workbench{grid-template-rows:42px minmax(0,1fr) 135px 52px}.c .track{padding:6px 10px}.c .track select{margin:2px 0}.c .meter{margin:6px 0}.c .branch-list{display:none}}
'''
tracks=''
for name,abbr,sound,branches in [('女高音','S','女声合唱',['女高 1','女高 2']),('女中音','A','女声合唱',[]),('男高音','T','男声合唱',[]),('男低音','B','男声合唱',['男低 1','男低 2']),('钢琴','P','原声钢琴',[])]:
 branch=''.join(f'<label><input type="checkbox" checked>{b}</label>' for b in branches)
 tracks+=f'<section class="track"><div class="track-title"><label><input class="enabled" type="checkbox" checked>{name}</label><button class="solo">独听</button></div><select aria-label="{name}音色"><option>{sound}</option><option>原声钢琴</option><option>纯音练习</option></select><div class="volume"><input type="range" value="78" aria-label="{name}音量"><span>78</span></div><div class="meter"></div>{"<div class=branch-list>"+branch+"</div>" if branches else ""}</section>'
SCRIPT='''
const song=SONG;const source='data:image/svg+xml;base64,SOURCE';LAYOUT
let zoom=100;const notation=document.getElementById('notation');
function render(){const width=Math.max(220,notation.clientWidth);const rows=layoutScore(song,width,zoom);notation.innerHTML=rows.map(row=>{const s=song.systems[row.system],p=song.pages[row.page];const tile=(x,w)=>`<svg viewBox="${x} ${s.y} ${w} ${s.height}" width="${w*row.scale}" height="${row.height}"><image href="${source}" width="${p.svgWidth}" height="${p.svgHeight}"/></svg>`;return `<div class="notation-row"><small>第 ${row.items[0].measure.label} — ${row.items.at(-1).measure.label} 小节 ${row.continuation?'· 续行':''}</small><div class="row-scroll"><div class="notation-line" style="width:${row.width}px;height:${row.height}px">${tile(s.x,row.headerWidth/row.scale)}${row.items.map(i=>tile(i.sourceLeft,i.sourceWidth)).join('')}<i class="shade"></i><i class="cursor"></i></div></div></div>`}).join('')}
let timer;new ResizeObserver(()=>{clearTimeout(timer);timer=setTimeout(render,60)}).observe(notation);
document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{zoom=Math.min(150,Math.max(75,zoom+Number(b.dataset.zoom)));document.querySelector('.zoom-label').textContent=zoom+'%';render()});
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{document.querySelector('.controls').classList.add('open');document.querySelector('.scrim').classList.add('open')});
function close(){document.querySelector('.controls').classList.remove('open');document.querySelector('.scrim').classList.remove('open')};document.querySelector('.close').onclick=close;document.querySelector('.scrim').onclick=close;
document.querySelectorAll('.solo').forEach(button=>button.onclick=()=>{const active=button.classList.toggle('on');document.querySelectorAll('.track').forEach(t=>{const own=t===button.closest('.track');t.classList.toggle('muted',active&&!own);t.querySelector('.enabled').checked=!active||own;if(!own)t.querySelector('.solo').classList.remove('on')})});
document.querySelector('[data-all]').onclick=()=>document.querySelectorAll('.track').forEach(t=>{t.classList.remove('muted');t.querySelector('.enabled').checked=true;t.querySelector('.solo').classList.remove('on')});
document.querySelectorAll('.volume input').forEach(input=>input.oninput=()=>input.nextElementSibling.textContent=input.value);
document.querySelector('.play').onclick=function(){const on=this.classList.toggle('on');this.textContent=on?'暂停':'播放'};render();
'''.replace('SONG',json.dumps(preview,ensure_ascii=False)).replace('SOURCE',svg).replace('LAYOUT',layout)
names={'a':('排练工作台','清晰的工具栏、谱面、分声部列表，接近常见制谱软件。'),'b':('纸质谱夹','暖白底、纸面排版，强调长时间看谱。'),'c':('声部调音台','深色工具区配白色谱纸，分声部和音色集中在下方。')}
for key,(name,description) in names.items():
 links=''.join(f'<a class="{"active" if k==key else ""}" href="{k}.html">{k.upper()} {n[0]}</a>' for k,n in names.items())
 title={'a':'合唱练习','b':'谱夹','c':'合唱排练台'}[key]
 html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>方案 {key.upper()} · {name}</title><style>{CSS}</style><body class="{key}">
<div class="variant"><nav>{links}</nav><span class="note">视觉参考 · 分声部与音色为交互示意，不播放音频</span></div>
<div class="workbench"><header class="toolbar"><div class="toolbar-left"><strong>{title}</strong><span class="divider"></span><span class="fine">曲目 / 敕勒歌</span></div><div class="toolbar-right"><button class="optional">曲库</button><button class="optional">循环练习</button><button data-open class="mobile-control">声部 / 音色</button><button>阅读设置</button></div></header>
<aside class="library"><h3>练习曲目</h3><button class="active">敕勒歌<span>混声四部 · 9 页</span></button><button>Let It Go<span>混声四部 · 19 页</span></button><div class="section">本次练习</div><p>第 6 — 9 小节<br>速度 68<br>按谱面力度</p></aside>
<main class="score"><div class="score-meta"><div><h1>敕勒歌</h1><p>刘洲 作曲　吴昊 编合唱</p></div><div class="view-tools"><button class="optional">原谱</button><button data-zoom="-25" aria-label="缩小">−</button><span class="zoom-label">100%</span><button data-zoom="25" aria-label="放大">＋</button></div></div><div class="paper-scroll"><div class="paper"><div class="paper-heading"><h2>敕 勒 歌</h2><p>混声合唱与钢琴 · 刘洲 作曲　吴昊 编合唱</p></div><div id="notation"></div></div></div></main>
<aside class="controls"><div class="control-title"><h2>声部与音色</h2><button class="close" aria-label="关闭">×</button><div class="preset"><button data-all>全声部</button></div></div><div class="tracks">{tracks}</div><label class="expression"><span>按原谱力度播放</span><input type="checkbox" checked></label><div class="status"><span>分声部可独立选择</span><span>本地音色</span></div></aside><div class="scrim"></div>
<footer class="footer"><div class="transport"><button aria-label="上一小节">上一节</button><button class="play">播放</button><button aria-label="下一小节">下一节</button><button class="optional">循环</button></div><div class="timeline"><time>0:18</time><input type="range" value="9" aria-label="进度"><time>4:08</time></div><label class="speed">速度<select><option>1.0 ×</option><option>0.75 ×</option><option>0.5 ×</option></select></label></footer></div><script>{SCRIPT}</script></body></html>'''
 (OUT/f'{key}.html').write_text(html,encoding='utf8')
gallery='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>合唱练习室 · 界面方案对比</title><style>*{box-sizing:border-box}body{margin:0;background:#e9eaec;color:#25282b;font:14px Arial,"Microsoft YaHei",sans-serif}header{padding:18px 24px;background:white;border-bottom:1px solid #ccc}h1{font-size:20px;margin:0 0 9px;font-weight:500}p{font-size:12px;line-height:1.8;color:#62686e;margin:0}.choices{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}button,a{font:inherit;border:1px solid #bfc4ca;background:white;border-radius:2px;padding:9px 13px;cursor:pointer;color:#333;text-decoration:none}button.active{background:#303942;color:white;border-color:#303942}.devices{display:flex;gap:7px;align-items:center;padding:12px 24px;flex-wrap:wrap;font-size:12px}.devices button{font-size:12px;padding:7px 10px}main{padding:0 18px 20px;overflow:auto;display:flex;justify-content:center}iframe{width:100%;height:calc(100dvh - 200px);min-height:520px;max-width:100%;border:1px solid #aeb4ba;background:white}a{font-size:12px;margin-left:auto}#caption{font-size:12px;color:#676e75;padding:0 24px 12px}@media(max-width:600px){header{padding:14px}h1{font-size:18px}.devices{padding:10px 14px}main{padding:0 5px 10px}iframe{height:calc(100dvh - 250px)}.devices a{margin:0}}</style><header><h1>合唱练习室 · 界面方案对比</h1><p>三份独立 HTML，可切换手机、平板、电脑宽度。使用原 PDF 谱面；分声部、音色选择和按钮仅作视觉交互示意。</p><div class="choices"><button class="active" data-theme="a">A 排练工作台</button><button data-theme="b">B 纸质谱夹</button><button data-theme="c">C 声部调音台</button></div></header><div class="devices"><span>预览尺寸</span><button data-width="390">手机 390</button><button data-width="768">平板竖屏 768</button><button data-width="1024">平板横屏 1024</button><button data-width="100%">电脑 / 铺满</button><a id="open" href="a.html" target="_blank">单独打开当前方案 ↗</a></div><div id="caption">A：紧凑、明确的操作区。曲库、乐谱和声部列表各有固定位置。</div><main><iframe id="preview" src="a.html" title="界面方案预览"></iframe></main><script>const captions={a:'A：紧凑、明确的操作区。曲库、乐谱和声部列表各有固定位置。',b:'B：优先阅读。暖白纸面、克制的控制栏，适合手机和平板长时间看谱。',c:'C：优先排练控制。深色工具区、下方分声部通道，突出音色、音量与独听。'};document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('preview').src=b.dataset.theme+'.html';document.getElementById('open').href=b.dataset.theme+'.html';document.getElementById('caption').textContent=captions[b.dataset.theme]});document.querySelectorAll('[data-width]').forEach(b=>b.onclick=()=>{document.getElementById('preview').style.width=b.dataset.width.endsWith('%')?b.dataset.width:b.dataset.width+'px';document.querySelectorAll('[data-width]').forEach(x=>x.classList.toggle('active',x===b))});</script></html>'''
(OUT/'index.html').write_text(gallery,encoding='utf8')
local=ROOT/'docs/design';local.mkdir(parents=True,exist_ok=True)
for file in OUT.glob('*.html'):(local/file.name).write_bytes(file.read_bytes())
